-- TXN-09: rules that fill in category / merchant / tags on NEW transactions whose description matches.
CREATE TABLE IF NOT EXISTS transactions."TransactionRules" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "Name" varchar(80) NOT NULL,
    "MatchText" varchar(120) NOT NULL,
    "MatchMode" integer NOT NULL DEFAULT 0,          -- 0 contains, 1 starts with, 2 equals
    "TypeFilter" integer NULL,                       -- NULL any, 0 income, 1 expense
    "MinAmount" numeric(18,2) NULL,
    "MaxAmount" numeric(18,2) NULL,
    "TransactionCategoryId" integer NULL,
    "MerchantId" integer NULL,
    "Tags" text NULL,                                -- packed like Transactions.Tags
    "Priority" integer NOT NULL DEFAULT 100,
    "IsActive" boolean NOT NULL DEFAULT true,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL,
    CONSTRAINT "PK_TransactionRules" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TransactionRules_Categories" FOREIGN KEY ("TransactionCategoryId") REFERENCES transactions."TransactionCategories" ("Id") ON DELETE SET NULL,
    CONSTRAINT "FK_TransactionRules_Merchants" FOREIGN KEY ("MerchantId") REFERENCES transactions."Merchants" ("Id") ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS "IX_TransactionRules_UserId_Priority" ON transactions."TransactionRules" ("UserId", "Priority");
